content:
:root {
  --bg-primary: #0f172a;
  --bg-secondary: #1e293b;
  --bg-tertiary: #334155;
  --text-primary: #f8fafc;
  --text-secondary: #94a3b8;
  --text-muted: #64748b;
  --accent-color: #38bdf8;
  --accent-hover: #0ea5e9;
  --accent-glow: rgba(56, 189, 248, 0.35);
  --success-color: #4ade80;
  --success-glow: rgba(74, 222, 128, 0.3);
  --warning-color: #fbbf24;
  --danger-color: #f87171;
  --danger-glow: rgba(248, 113, 113, 0.4);
  --border-color: #334155;
  --border-light: #475569;
  --card-bg: rgba(30, 41, 59, 0.85);
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Hiragino Sans', 'Noto Sans JP', sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Courier New', monospace;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-full: 9999px;
  --shadow-sm: 0 2px 4px rgba(0, 0, 0, 0.2);
  --shadow-md: 0 4px 12px rgba(0, 0, 0, 0.3);
  --shadow-lg: 0 8px 24px rgba(0, 0, 0, 0.4);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-primary);
  background-image: 
    radial-gradient(at 0% 0%, rgba(56, 189, 248, 0.12) 0px, transparent 50%),
    radial-gradient(at 100% 100%, rgba(99, 102, 241, 0.12) 0px, transparent 50%);
  background-attachment: fixed;
  color: var(--text-primary);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  overflow-x: hidden;
}

#root {
  width: 100%;
  display: flex;
  justify-content: center;
}

/* アプリケーション全体コンテナ */
.app {
  width: 100%;
  max-width: 860px;
  min-height: 100vh;
  padding: 24px 16px 40px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

/* ヘッダーエリア */
.header {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 8px;
  width: 100%;
}

.title {
  font-size: 2rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 10px;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.4);
}

.subtitle {
  font-size: 0.95rem;
  color: var(--text-secondary);
  font-weight: 400;
}

.badge {
  display: inline-flex;
  align-items: center;
  padding: 4px 10px;
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  background: rgba(56, 189, 248, 0.15);
  color: var(--accent-color);
  border: 1px solid rgba(56, 189, 248, 0.3);
}

/* ステータスバー（残り時間 & 統計バッジ） */
.status-bar {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  padding: 12px 16px;
  background: var(--card-bg);
  backdrop-filter: blur(8px);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
}

.timer-box {
  display: flex;
  align-items: baseline;
  gap: 8px;
  background: rgba(15, 23, 42, 0.6);
  padding: 6px 14px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
}

.timer-label {
  font-size: 0.8rem;
  color: var(--text-secondary);
  font-weight: 600;
}

.timer-value {
  font-family: var(--font-mono);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--accent-color);
  min-width: 42px;
  text-align: right;
  transition: color 0.2s ease;
}

.timer-value-danger {
  color: var(--danger-color);
  will-change: transform;
  animation: pulse-danger 1s infinite alternate;
}

@keyframes pulse-danger {
  0% {
    transform: scale(1);
    text-shadow: 0 0 4px var(--danger-glow);
  }
  100% {
    transform: scale(1.08);
    text-shadow: 0 0 12px var(--danger-glow);
  }
}

.stat-chip {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: rgba(15, 23, 42, 0.5);
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
  min-width: 70px;
}

.stat-chip-label {
  font-size: 0.7rem;
  color: var(--text-muted);
  font-weight: 500;
}

.stat-chip-value {
  font-family: var(--font-mono);
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-primary);
}

/* メインカード */
.card {
  width: 100%;
  background: var(--card-bg);
  backdrop-filter: blur(12px);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  box-shadow: var(--shadow-md);
  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
  overflow: hidden;
}

/* 単語表示エリア */
.word-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  gap: 12px;
  width: 100%;
  min-height: 150px;
}

.kanji-text {
  font-size: 2.2rem;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: 0.05em;
  text-shadow: 0 2px 8px rgba(0, 0, 0, 0.4);
}

.kana-text {
  font-size: 1.15rem;
  font-weight: 500;
  color: var(--text-secondary);
  letter-spacing: 0.08em;
}

.romaji-display {
  font-family: var(--font-mono);
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  padding: 8px 16px;
  background: rgba(15, 23, 42, 0.7);
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
  min-height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  max-width: 100%;
  word-break: break-all;
}

/* 文字状態スタイル */
.char-correct {
  color: var(--success-color);
  text-shadow: 0 0 8px var(--success-glow);
}

.char-current {
  color: var(--accent-color);
  background: rgba(56, 189, 248, 0.25);
  border-radius: 4px;
  padding: 0 2px;
  position: relative;
  text-decoration: underline;
  text-underline-offset: 4px;
  animation: blink-current 1.2s infinite;
}

@keyframes blink-current {
  0%, 100% {
    background: rgba(56, 189, 248, 0.35);
  }
  50% {
    background: rgba(56, 189, 248, 0.1);
  }
}

.char-remaining {
  color: var(--text-muted);
}

.char-error {
  color: var(--danger-color);
  background: rgba(248, 113, 113, 0.25);
  border-radius: 4px;
  padding: 0 2px;
  will-change: transform;
  animation: shake 0.25s ease-in-out;
}

@keyframes shake {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-3px); }
  75% { transform: translateX(3px); }
}

/* 入力エリア・隠しインプット（モバイル・アクセシビリティ対応） */
.input-area {
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  margin-top: 12px;
}

.hidden-input {
  position: absolute;
  opacity: 0;
  pointer-events: auto;
  width: 100%;
  height: 100%;
  top: 0;
  left: 0;
  cursor: default;
  z-index: 1;
}

.input-notice {
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-top: 8px;
}

/* 仮想キーボード */
.keyboard {
  width: 100%;
  max-width: 680px;
  background: rgba(15, 23, 42, 0.75);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  box-shadow: var(--shadow-md);
  user-select: none;
}

.keyboard-row {
  display: flex;
  justify-content: center;
  gap: 6px;
  width: 100%;
}

.key {
  flex: 1;
  max-width: 52px;
  min-width: 0;
  height: 44px;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-family: var(--font-mono);
  font-size: 0.95rem;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.1s ease;
  box-shadow: 0 2px 0 rgba(0, 0, 0, 0.4);
}

.key:hover {
  background: #3e4f69;
  transform: translateY(-1px);
}

.key:active {
  transform: translateY(1px);
  box-shadow: 0 0 0 rgba(0, 0, 0, 0.4);
}

.key-active {
  background: var(--accent-color) !important;
  color: #0f172a !important;
  font-weight: 800;
  border-color: #7dd3fc !important;
  box-shadow: 0 0 12px var(--accent-glow), inset 0 1px 0 rgba(255, 255, 255, 0.5);
  transform: scale(1.05);
  z-index: 2;
}

.key-space {
  flex: 4;
  max-width: 240px;
  font-size: 0.8rem;
}

/* リザルト画面 */
.result-card {
  width: 100%;
  max-width: 580px;
  background: var(--card-bg);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
  box-shadow: var(--shadow-lg);
  backdrop-filter: blur(16px);
  animation: fadeIn 0.4s ease-out;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.result-header {
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.result-title {
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--text-primary);
}

.result-score-banner {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 6px;
  margin: 8px 0;
}

.result-score-num {
  font-family: var(--font-mono);
  font-size: 3.5rem;
  font-weight: 900;
  color: var(--accent-color);
  line-height: 1;
}

.result-score-unit {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-secondary);
}

.result-rank-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 6px 18px;
  border-radius: var(--radius-full);
  font-size: 1.2rem;
  font-weight: 800;
  background: linear-gradient(135deg, #f59e0b, #ec4899);
  color: #fff;
  box-shadow: 0 4px 12px rgba(245, 158, 11, 0.4);
}

.result-grid {
  width: 100%;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
}

.result-item {
  background: rgba(15, 23, 42, 0.6);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 12px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.result-item-title {
  font-size: 0.8rem;
  color: var(--text-secondary);
  font-weight: 600;
}

.result-item-val {
  font-family: var(--font-mono);
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--text-primary);
}

/* ボタン群 */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 24px;
  font-size: 1rem;
  font-weight: 700;
  border-radius: var(--radius-md);
  border: none;
  cursor: pointer;
  transition: all 0.2s ease;
  user-select: none;
  min-height: 48px;
}

.btn-primary {
  background: var(--accent-color);
  color: #0f172a;
  box-shadow: 0 4px 14px var(--accent-glow);
}

.btn-primary:hover {
  background: var(--accent-hover);
  transform: translateY(-2px);
  box-shadow: 0 6px 20px var(--accent-glow);
}

.btn-primary:active {
  transform: translateY(0);
}

/* 操作説明 & キーヒント */
.instructions {
  font-size: 0.9rem;
  color: var(--text-secondary);
  text-align: center;
  line-height: 1.6;
}

.key-hint {
  display: inline-block;
  padding: 2px 6px;
  font-family: var(--font-mono);
  font-size: 0.8rem;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-light);
  border-radius: 4px;
  color: var(--text-primary);
  margin: 0 2px;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.2);
}

/* レスポンシブ対応 */
@media (max-width: 640px) {
  .app {
    padding: 12px 8px 24px;
    gap: 12px;
  }

  .title {
    font-size: 1.35rem;
  }

  .subtitle {
    font-size: 0.85rem;
  }

  .status-bar {
    padding: 8px 10px;
    gap: 8px;
    justify-content: center;
  }

  .timer-box {
    padding: 4px 10px;
  }

  .timer-value {
    font-size: 1.25rem;
  }

  .stat-chip {
    padding: 4px 8px;
    min-width: 56px;
  }

  .stat-chip-label {
    font-size: 0.65rem;
  }

  .stat-chip-value {
    font-size: 1rem;
  }

  .card {
    padding: 20px 14px;
  }

  .word-container {
    min-height: 110px;
    gap: 8px;
  }

  .kanji-text {
    font-size: 1.5rem;
  }

  .kana-text {
    font-size: 1rem;
  }

  .romaji-display {
    font-size: 1.2rem;
    letter-spacing: 0.06em;
    padding: 6px 10px;
    min-height: 40px;
  }

  .keyboard {
    padding: 6px 4px;
    gap: 4px;
  }

  .keyboard-row {
    gap: 3px;
  }

  .key {
    height: 36px;
    font-size: 0.8rem;
  }

  .key-space {
    max-width: 180px;
  }

  .result-card {
    padding: 20px 14px;
    gap: 16px;
  }

  .result-title {
    font-size: 1.4rem;
  }

  .result-score-num {
    font-size: 2.5rem;
  }

  .result-grid {
    grid-template-columns: 1fr;
    gap: 8px;
  }
}

@media (max-height: 600px) and (orientation: landscape) {
  .app {
    padding: 8px 12px 16px;
    gap: 8px;
  }

  .header {
    gap: 4px;
  }

  .badge,
  .subtitle {
    display: none;
  }

  .title {
    font-size: 1.2rem;
  }

  .status-bar {
    padding: 4px 8px;
    gap: 6px;
  }

  .card {
    padding: 12px;
  }

  .word-container {
    min-height: auto;
    gap: 4px;
  }

  .kanji-text {
    font-size: 1.3rem;
  }

  .kana-text {
    font-size: 0.9rem;
  }

  .romaji-display {
    font-size: 1.1rem;
    min-height: 34px;
    padding: 4px 8px;
  }

  .key {
    height: 30px;
    font-size: 0.75rem;
  }
}

/**
 * 単語データの型定義
 */
export interface WordItem {
  /** 一意なID */
  id: number;
  /** 漢字表記テキスト */
  kanji: string;
  /** ひらがな読み */
  kana: string;
  /** 入力対象のローマ字（ヘボン式基準） */
  romaji: string;
}

/**
 * ゲームの進行状態
 * ready: 開始前待機状態
 * playing: プレイ中
 * finished: 制限時間終了・リザルト表示状態
 */
export type GameState = 'ready' | 'playing' | 'finished';

/**
 * プレイ中の打鍵統計およびリザルト情報
 */
export interface TypingStats {
  /** 正しく入力された累計文字数（文字） */
  correctChars: number;
  /** キーボードを押下した総回数（回） */
  totalKeystrokes: number;
  /** タイプミスした回数（回） */
  missCount: number;
  /** 入力を完了した単語数（単語） */
  completedWords: number;
  /** 入力正答率（0〜100%） */
  accuracy: number;
  /** CPM (Characters Per Minute): 1分間あたりの文字入力速度（打鍵/分） */
  cpm: number;
  /** WPM (Words Per Minute): 1分間あたりの単語入力速度（語/分, 5文字換算） */
  wpm: number;
}

/**
 * スコアに応じたランク評価情報
 */
export interface RankResult {
  /** ランク称号（例: 'S+', 'A', 'B'） */
  rank: string;
  /** ランクに対する解説ラベル */
  label: string;
}

