import { useState, useCallback } from 'react';

interface VirtualKeyboardProps {
  activeKey?: string;
  onKeyPress?: (key: string) => void;
}

// 3段アルファベット配列 + ローマ字長音入力用ハイフン
// 数字段を省略したミニマル配列のため、ローマ字入力で多用される長音記号「-」をQWERTY最上段末尾に配置
const KEYBOARD_ROWS = [
  ['q', 'w', 'e', 'r', 't', 'y', 'u', 'i', 'o', 'p', '-'],
  ['a', 's', 'd', 'f', 'g', 'h', 'j', 'k', 'l'],
  ['z', 'x', 'c', 'v', 'b', 'n', 'm'],
];

export default function VirtualKeyboard({ activeKey = '', onKeyPress }: VirtualKeyboardProps) {
  const [pressedKey, setPressedKey] = useState<string | null>(null);
  const normalizedActive = activeKey.toLowerCase();

  const handleKeyClick = useCallback(
    (key: string) => {
      setPressedKey(key.toLowerCase());
      onKeyPress?.(key);
      setTimeout(() => {
        setPressedKey((current) => (current === key.toLowerCase() ? null : current));
      }, 120);
    },
    [onKeyPress]
  );

  const getAriaLabel = (char: string) => {
    if (char === '-') return 'キー ハイフン';
    if (char === ' ') return 'スペースキー';
    return `キー ${char.toUpperCase()}`;
  };

  return (
    <div className="keyboard" role="group" aria-label="仮想キーボード">
      {KEYBOARD_ROWS.map((row, rowIndex) => (
        <div key={rowIndex} className="keyboard-row">
          {row.map((char) => {
            const lowerChar = char.toLowerCase();
            const isActive = normalizedActive === lowerChar || pressedKey === lowerChar;
            const keyClass = isActive ? 'key key-active' : 'key';

            return (
              <button
                key={char}
                type="button"
                className={keyClass}
                onClick={() => handleKeyClick(char)}
                tabIndex={-1}
                aria-label={getAriaLabel(char)}
                aria-pressed={isActive}
              >
                {char.toUpperCase()}
              </button>
            );
          })}
        </div>
      ))}
      <div className="keyboard-row">
        <button
          type="button"
          className={
            normalizedActive === ' ' || pressedKey === ' '
              ? 'key key-space key-active'
              : 'key key-space'
          }
          onClick={() => handleKeyClick(' ')}
          tabIndex={-1}
          aria-label={getAriaLabel(' ')}
          aria-pressed={normalizedActive === ' ' || pressedKey === ' '}
        >
          SPACE
        </button>
      </div>
    </div>
  );
}

import { useState, useEffect, useRef, useCallback } from 'react';
import { GameState, WordItem, TypingStats } from './types';
import { WORDS } from './data/words';
import { calculateRank } from './utils/rank';
import VirtualKeyboard from './components/VirtualKeyboard';

const GAME_DURATION = 60;

function shuffleWords(words: WordItem[]): WordItem[] {
  const array = [...words];
  for (let i = array.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
  return array;
}

export default function App() {
  const [gameState, setGameState] = useState<GameState>('ready');
  const [timeLeft, setTimeLeft] = useState<number>(GAME_DURATION);
  const [wordList, setWordList] = useState<WordItem[]>(() => shuffleWords(WORDS));
  const [wordIndex, setWordIndex] = useState<number>(0);
  const [charIndex, setCharIndex] = useState<number>(0);
  const [hasError, setHasError] = useState<boolean>(false);
  const [isImeActive, setIsImeActive] = useState<boolean>(false);

  // 打鍵統計
  const [correctChars, setCorrectChars] = useState<number>(0);
  const [totalKeystrokes, setTotalKeystrokes] = useState<number>(0);
  const [missCount, setMissCount] = useState<number>(0);
  const [completedWords, setCompletedWords] = useState<number>(0);

  const inputRef = useRef<HTMLInputElement>(null);
  const isComposingRef = useRef<boolean>(false);
  const errorTimeoutRef = useRef<number | null>(null);

  const currentWord: WordItem = wordList[wordIndex] || WORDS[0];
  const targetRomaji = currentWord.romaji.toLowerCase();
  const currentChar = charIndex < targetRomaji.length ? targetRomaji[charIndex] : '';

  // エラータイマークリア処理
  const clearErrorTimer = useCallback(() => {
    if (errorTimeoutRef.current !== null) {
      window.clearTimeout(errorTimeoutRef.current);
      errorTimeoutRef.current = null;
    }
  }, []);

  // アンマウント時のタイマークリーンアップ
  useEffect(() => {
    return () => {
      clearErrorTimer();
    };
  }, [clearErrorTimer]);

  // ゲームスタート
  const startGame = useCallback(() => {
    clearErrorTimer();
    const shuffled = shuffleWords(WORDS);
    setWordList(shuffled);
    setWordIndex(0);
    setCharIndex(0);
    setTimeLeft(GAME_DURATION);
    setCorrectChars(0);
    setTotalKeystrokes(0);
    setMissCount(0);
    setCompletedWords(0);
    setHasError(false);
    setIsImeActive(false);
    setGameState('playing');

    if (inputRef.current) {
      inputRef.current.value = '';
    }

    setTimeout(() => {
      inputRef.current?.focus();
    }, 50);
  }, [clearErrorTimer]);

  // 60秒タイマー
  useEffect(() => {
    if (gameState !== 'playing') return;

    if (timeLeft <= 0) {
      setGameState('finished');
      return;
    }

    const timer = setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 1) {
          clearInterval(timer);
          setGameState('finished');
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(timer);
  }, [gameState, timeLeft]);

  // キー入力処理
  const handleInputCharacter = useCallback((inputKey: string) => {
    if (gameState !== 'playing') {
      if (inputKey === ' ') {
        startGame();
      }
      return;
    }

    const lowerInput = inputKey.toLowerCase();
    const expected = targetRomaji[charIndex];

    setTotalKeystrokes((prev) => prev + 1);

    if (lowerInput === expected) {
      clearErrorTimer();
      setHasError(false);
      setCorrectChars((prev) => prev + 1);

      const nextCharIndex = charIndex + 1;
      if (nextCharIndex >= targetRomaji.length) {
        // 単語完了
        setCompletedWords((prev) => prev + 1);
        setWordIndex((prev) => (prev + 1) % wordList.length);
        setCharIndex(0);
      } else {
        setCharIndex(nextCharIndex);
      }
    } else {
      // ミス打鍵: 既存タイマーを破棄して点滅状態を安定化
      clearErrorTimer();
      setMissCount((prev) => prev + 1);
      setHasError(true);
      errorTimeoutRef.current = window.setTimeout(() => {
        setHasError(false);
        errorTimeoutRef.current = null;
      }, 250);
    }
  }, [gameState, targetRomaji, charIndex, wordList.length, startGame, clearErrorTimer]);

  // キーボードイベントハンドラ
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // IME変換中または未確定状態は処理を抑止
      if (e.isComposing || e.keyCode === 229 || isComposingRef.current) {
        return;
      }

      // スタート前のスペースキー
      if (gameState === 'ready' && e.code === 'Space') {
        e.preventDefault();
        startGame();
        return;
      }

      if (gameState === 'finished' && (e.code === 'Space' || e.code === 'Enter')) {
        e.preventDefault();
        startGame();
        return;
      }

      if (gameState !== 'playing') return;

      // 特殊キー無視
      if (e.key.length === 1 && !e.ctrlKey && !e.metaKey && !e.altKey) {
        e.preventDefault();
        handleInputCharacter(e.key);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [gameState, handleInputCharacter, startGame]);

  // 画面クリックで隠しinputにフォーカス
  const handleContainerClick = () => {
    inputRef.current?.focus();
  };

  // IMEイベントハンドラ
  const handleCompositionStart = () => {
    isComposingRef.current = true;
    setIsImeActive(true);
  };

  const handleCompositionEnd = (e: React.CompositionEvent<HTMLInputElement>) => {
    isComposingRef.current = false;
    // 確定された文字を即座にクリアして意図しない日本語文字列入力を防止
    if (inputRef.current) {
      inputRef.current.value = '';
    }
    // 短時間でIME通知をリセット
    setTimeout(() => {
      if (!isComposingRef.current) {
        setIsImeActive(false);
      }
    }, 1500);
  };

  // 統計計算
  const accuracy = totalKeystrokes > 0 ? Math.round((correctChars / totalKeystrokes) * 100) : 100;
  const elapsedSec = GAME_DURATION - timeLeft || 1;
  const cpm = Math.round((correctChars / elapsedSec) * 60);
  const wpm = Math.round(cpm / 5);

  const stats: TypingStats = {
    correctChars,
    totalKeystrokes,
    missCount,
    completedWords,
    accuracy,
    cpm,
    wpm,
  };

  const rankInfo = calculateRank(stats.correctChars, stats.accuracy);

  return (
    <div className="app" onClick={handleContainerClick}>
      {/* 隠しインプット（モバイルキーボード・IMEフォーカス対応） */}
      <input
        ref={inputRef}
        type="text"
        className="hidden-input"
        autoCapitalize="none"
        autoComplete="off"
        autoCorrect="off"
        spellCheck="false"
        onCompositionStart={handleCompositionStart}
        onCompositionEnd={handleCompositionEnd}
        onChange={(e) => {
          if (isComposingRef.current) return;
          const val = e.target.value;
          if (val.length > 0) {
            handleInputCharacter(val[val.length - 1]);
            e.target.value = '';
          }
        }}
      />

      <header className="header">
        <div className="badge">ROMAJI TYPING PRACTICE</div>
        <h1 className="title">
          <span>⚡</span> 60秒タイピングマスター
        </h1>
        <p className="subtitle">制限時間60秒で正確かつ高速にローマ字を入力しよう！</p>
      </header>

      {/* プレイ中のステータスバー */}
      <div className="status-bar">
        <div className="timer-box">
          <span className="timer-label">TIME</span>
          <span className={timeLeft <= 10 && gameState === 'playing' ? 'timer-value timer-value-danger' : 'timer-value'}>
            {timeLeft}s
          </span>
        </div>

        <div className="stat-chip">
          <span className="stat-chip-label">打鍵数</span>
          <span className="stat-chip-value">{correctChars}</span>
        </div>

        <div className="stat-chip">
          <span className="stat-chip-label">正答率</span>
          <span className="stat-chip-value">{accuracy}%</span>
        </div>

        <div className="stat-chip">
          <span className="stat-chip-label">ミス</span>
          <span className="stat-chip-value">{missCount}</span>
        </div>

        <div className="stat-chip">
          <span className="stat-chip-label">WPM</span>
          <span className="stat-chip-value">{wpm}</span>
        </div>
      </div>

      {/* メイン画面の分岐 */}
      {gameState === 'ready' && (
        <div className="card">
          <div className="word-container">
            <div className="kanji-text">準備はいいですか？</div>
            <div className="kana-text">じゅんびはいいですか？</div>
            <div className="romaji-display">
              <span className="char-current">S</span>
              <span className="char-remaining">TART</span>
            </div>
          </div>
          <div className="input-area">
            <button type="button" className="btn btn-primary" onClick={startGame}>
              スタート (SPACE)
            </button>
            <p className="input-notice">
              キーボードの <span className="key-hint">Space</span> を押すか、ボタンをクリックして開始
            </p>
          </div>
        </div>
      )}

      {gameState === 'playing' && (
        <div className="card">
          <div className="word-container">
            <div className="kanji-text">{currentWord.kanji}</div>
            <div className="kana-text">{currentWord.kana}</div>

            <div className="romaji-display">
              {targetRomaji.split('').map((char, index) => {
                let charStyle = 'char-remaining';
                if (index < charIndex) {
                  charStyle = 'char-correct';
                } else if (index === charIndex) {
                  charStyle = hasError ? 'char-error' : 'char-current';
                }

                return (
                  <span key={index} className={charStyle}>
                    {char}
                  </span>
                );
              })}
            </div>
          </div>

          <div className="input-area">
            <p className="instructions">
              次の文字: <span className="key-hint">{currentChar.toUpperCase() || 'SPACE'}</span>
            </p>
            {isImeActive && (
              <p className="input-notice">
                ※ 日本語入力(IME)がオンになっています。半角英数入力に切り替えてください。
              </p>
            )}
          </div>
        </div>
      )}

      {gameState === 'finished' && (
        <div className="result-card">
          <div className="result-header">
            <div className="result-rank-badge">ランク: {rankInfo.rank} ({rankInfo.label})</div>
            <h2 className="result-title">タイムアップ！</h2>
            <div className="result-score-banner">
              <span className="result-score-num">{correctChars}</span>
              <span className="result-score-unit">文字</span>
            </div>
          </div>

          <div className="result-grid">
            <div className="result-item">
              <span className="result-item-title">入力正答率</span>
              <span className="result-item-val">{accuracy}%</span>
            </div>
            <div className="result-item">
              <span className="result-item-title">WPM (ワード/分)</span>
              <span className="result-item-val">{wpm}</span>
            </div>
            <div className="result-item">
              <span className="result-item-title">CPM (文字/分)</span>
              <span className="result-item-val">{cpm}</span>
            </div>
            <div className="result-item">
              <span className="result-item-title">クリア単語数</span>
              <span className="result-item-val">{completedWords} 問</span>
            </div>
            <div className="result-item">
              <span className="result-item-title">総打鍵数</span>
              <span className="result-item-val">{totalKeystrokes} 回</span>
            </div>
            <div className="result-item">
              <span className="result-item-title">ミス入力数</span>
              <span className="result-item-val">{missCount} 回</span>
            </div>
          </div>

          <button type="button" className="btn btn-primary" onClick={startGame}>
            もう一度挑戦する (SPACE)
          </button>
        </div>
      )}

      {/* 仮想キーボード */}
      <VirtualKeyboard
        activeKey={gameState === 'playing' ? currentChar : gameState === 'ready' ? ' ' : ''}
        onKeyPress={(key) => handleInputCharacter(key)}
      />
    </div>
  );
}

import { RankResult } from '../types';

/**
 * 打鍵文字数と正答率からランク評価を算出する
 * @param correctChars 正しく入力された文字数
 * @param accuracy 正答率（0-100%）
 * @returns ランク称号と解説ラベル
 */
export function calculateRank(correctChars: number, accuracy: number): RankResult {
  if (correctChars >= 350 && accuracy >= 95) return { rank: 'S+', label: 'タイピングマスター級' };
  if (correctChars >= 300 && accuracy >= 90) return { rank: 'S', label: '超達人級' };
  if (correctChars >= 240 && accuracy >= 85) return { rank: 'A', label: '上級者級' };
  if (correctChars >= 180 && accuracy >= 80) return { rank: 'B', label: '中級者級' };
  if (correctChars >= 120) return { rank: 'C', label: '初級者級' };
  return { rank: 'D', label: 'ビギナー級' };
}
